async function main(){
  const page = figma.getNodeById('49:2');
  await figma.setCurrentPageAsync(page);

  // Load fonts
  const fonts = [
    {family:"DM Sans", style:"Regular"},{family:"DM Sans", style:"Medium"},{family:"DM Sans", style:"Bold"},
    {family:"Inter", style:"Regular"},{family:"Inter", style:"Medium"},{family:"Inter", style:"Semi Bold"},{family:"Inter", style:"Bold"}
  ];
  for(const f of fonts){ try{ await figma.loadFontAsync(f); }catch(e){ console.log("font fail", f.family, f.style); } }

  // Palette
  const C = {
    brand:"31A062", brandDark:"1F7A4A", brandTint:"E6F3EC",
    bg:"F6F7F9", surface:"FFFFFF", ink:"171B26", ink2:"6A7182", ink3:"9AA1B0",
    border:"E9EBF0", loss:"E5484D", gold:"D9A441", goldSoft:"F7ECDA",
    silver:"AEB3BD", silverSoft:"ECEEF2", platinum:"8F9CBA", platinumSoft:"E7EAF2",
    tile:"F0F3F6"
  };
  const hex=(h)=>({r:parseInt(h.slice(0,2),16)/255,g:parseInt(h.slice(2,4),16)/255,b:parseInt(h.slice(4,6),16)/255});

  function T(text,size,weight,family,color){
    const t=figma.createText();
    t.characters=text;
    t.fontSize=size;
    t.fontName={family:family||"Inter",style:weight};
    t.fills=[{type:'SOLID',color:hex(color)}];
    return t;
  }
  function TAligned(t,align){t.textAlignHorizontal=align;return t;}
  function Rect(w,h,fill,radius){
    const r=figma.createRectangle();
    if(w&&h)r.resize(w,h);
    r.fills=fill?[{type:'SOLID',color:hex(fill)}]:[];
    if(radius)r.cornerRadius=radius;
    return r;
  }
  function Frame(name,w,h,x,y,fill,radius,stroke){
    const f=figma.createFrame();
    f.name=name; f.resize(w,h);
    f.x=x||0; f.y=y||0;
    if(fill)f.fills=[{type:'SOLID',color:hex(fill)}];
    else f.fills=[];
    if(radius)f.cornerRadius=radius;
    if(stroke){f.strokes=[{type:'SOLID',color:hex(stroke)}];f.strokeWeight=1;}
    return f;
  }
  function fmt(container,n){container.appendChild(n); return n;}
  function comp(node){ return node; }

  // ---- Component container ----
  let cy=0;
  function section(name,w,h){
    return Frame(name,w,h,0,cy,"FFFFFF");
  }

  // ===== STATUS BAR component (414x44) =====
  function makeStatusBar(){
    const f=Frame("Status Bar",414,44);
    let barT=TAligned(T("9:41",16,"Semi Bold","Inter","171B26"),"CENTER");
    barT.resize(50,20); barT.x=182;barT.y=14; fmt(f,barT);
    // signals right
    let sig=Rect(14,10,null);
    // battery
    const bat=Frame("bat",26,12,372,17,null,1,"171B26");
    const cap=Rect(22,6,"171B26",2);cap.x=1;cap.y=2;fmt(bat,cap);
    fmt(f,bat);
    // signal dots
    const sigd=Frame("sig",18,12,348,17);
    for(let i=0;i<4;i++){let d=Rect(3,3+(i));d.x=i*4;d.y=9-(i);d.cornerRadius=1.5;d.fills=[{type:'SOLID',color:hex("171B26")}];fmt(sigd,d);}
    fmt(f,sigd);
    return f;
  }
  // ===== HOME INDICATOR (414x34) =====
  function makeHomeIndicator(){
    const f=Frame("Home Indicator",414,34);
    const h=Rect(134,5,"171B26");h.x=140;h.y=21;h.cornerRadius=3;fmt(f,h);
    return f;
  }

  // ===== BUTTON component (354x60 radius20) =====
  function makeButton(compName,label,state){
    const f=Frame(compName,354,60);
    f.layoutMode="HORIZONTAL"; f.primaryAxisAlignItems="CENTER"; f.counterAxisAlignItems="CENTER";
    f.cornerRadius=20; f.fills=[{type:'SOLID',color:hex(state==="disabled"?"B8CDC1":state==="secondary"?"E6F3EC":"31A062")}];
    const t=T(label,17,"Semi Bold","Inter",state==="disabled"?"8FBFAA":"FFFFFF");
    if(state==="secondary")t.fills=[{type:'SOLID',color:hex("1F7A4A")}];
    fmt(f,t);
    const c=figma.createComponent(); 
    // copy node into component
    c.resize(f.width,f.height);
    for(const child of f.children){c.appendChild(child);}
    c.name=compName; c.fills=f.fills;
    c.strokeWeight=0;
    return c;
  }

  // ===== TEXT FIELD component =====
  function makeTextField(compName,label,variant,state){
    const f=Frame(compName,354,60);
    f.cornerRadius=16; 
    f.strokes=[{type:'SOLID',color:hex(state==="error"?"E5484D":"D6DAE2")}]; f.strokeWeight=1;
    f.fills=[{type:'SOLID',color:hex("FFFFFF")}];
    if(state==="error"){f.fills=[{type:'SOLID',color:hex("FDF1F1")}]}
    const t=T(label,15,"Regular","Inter",state==="error"?"E5484D":"8A919F");
    t.x=18;t.y=20;fmt(f,t);
    const c=figma.createComponent();
    for(const child of f.children){c.appendChild(child);}
    c.resize(f.width,f.height);c.fills=f.fills;c.strokeWeight=1;c.strokes=f.strokes;c.cornerRadius=16;
    c.name=compName;
    return c;
  }

  // ===== Back Header component =====
  function makeBackHeader(compName,title){
    const f=Frame(compName,414,56);
    const back=Frame("back",40,40,16,8);
    // chevron-left drawn as vector
    const b=Rect(12,2,"171B26",1); b.x=8;b.y=19;
    // draw simple back arrow with two lines
    const line1=Rect(14,2,"171B26",1); line1.x=8;line1.y=19; fmt(back,line1);
    const line2=Rect(14,2,"171B26",1); line2.x=8;line2.y=19; line2.rotation=45; fmt(back,line2);
    fmt(f,back);
    const tt=T(title,20,"Bold","DM Sans","171B26"); tt.x=66;tt.y=14; fmt(f,tt);
    return f;
  }

  // ===== Bottom Nav component =====
  function makeBottomNav(compName,activeIdx){
    const f=Frame(compName,414,84);
    f.fills=[{type:'SOLID',color:hex("FFFFFF")}];
    f.strokes=[{type:'SOLID',color:hex("EDEFF3")}];f.strokeWeight=1;
    const items=[["Icon_Tab_Home","Home"],["Icon_Tab_Product_Search","Product"],["Icon_Tab_Transaction","Transaction"],["Icon_Tab_Account","Account"]];
    const icons=[{n:"home",p:"M8 4l-6 6v6h4v-4h4v4h4v-6z"},{n:"search",p:"M11 4a7 7 0 100 14 7 7 0 000-14zm0 12a5 5 0 1110 0 5 5 0 01-10 0z"},{n:"tx",p:"M4 7h16M8 7V5h8v2M6 10h12M6 10v8h12v-8M6 14h12"}];
    f.layoutMode="HORIZONTAL"; f.primaryAxisAlignItems="SPACE_BETWEEN"; f.counterAxisAlignItems="CENTER";
    f.paddingLeft=28;f.paddingRight=28;f.itemSpacing=0;f.verticalAlignItems="CENTER";
    for(let i=0;i<4;i++){
      const active=(i===activeIdx);
      const it=Frame(items[i][0],70,60,null,null,"FFFFFF");
      it.layoutMode="VERTICAL";it.primaryAxisAlignItems="CENTER";it.counterAxisAlignItems="CENTER";it.itemSpacing=4;
      // draw icon with vector
      const iv=figma.createVector();
      // simple use of vectorPaths via drawing
      iv.resize(22,22);
      const isIcon = items[i][0];
      // use internal path
      iv.vectorPaths=[{windingRule:"NONZERO",data:"M4 5.5a1.5 1.5 0 100 3 1.5 1.5 0 000-3zM4 12a1.5 1.5 0 100 3 1.5 1.5 0 000-3z"}];
      iv.fills=[{type:'SOLID',color:hex(active?"31A062":"9AA1B0")}];
      it.appendChild(iv);
      const lb=T(items[i][1],10,"Medium","Inter",active?"31A062":"9AA1B0");
      lb.resize(70,14);lb.textAlignHorizontal="CENTER";
      it.appendChild(lb);
      f.appendChild(it);
    }
    // make component copy
    const c=figma.createComponent();
    for(const child of f.children){c.appendChild(child);}
    c.resize(f.width,f.height);c.fills=f.fills;c.strokes=f.strokes;c.strokeWeight=1;
    c.name=compName;
    return c;
  }

  // Build & place on page (components as components, position left)
  const compFrame=Frame("SYSTEM / Components",1200,1200,0,0,"FFFFFF");
  page.appendChild(compFrame);

  // status bar & home indicator as components
  const sb=makeStatusBar(); sb.name="Status Bar / Default"; compFrame.appendChild(sb); sb.x=24;sb.y=24;
  const hi=makeHomeIndicator(); hi.name="Home Indicator"; compFrame.appendChild(hi); hi.x=24;hi.y=80;

  // button variants
  let bx=24, by=140;
  for(const st of ["default","disabled","secondary"]){
    const b=makeButton("Button / Primary "+st, st==="secondary"?"Login":"Create account", st);
    b.x=bx;b.y=by;compFrame.appendChild(b);bx+=390;
  }
  const bf=makeButton("Button / Primary Filled","Create account","default"); bf.x=24;by+=84;compFrame.appendChild(bf);

