  const tf5=makeTextField("Text Field / Password","Password","pass","empty");tf5.x=tx;tf5.y=by;compFrame.appendChild(tf5);

  const bb=makeBackHeader("Header / Back","Create an account");bb.x=24;by+=120;compFrame.appendChild(bb);
  const h1=Frame("Header / Title",414,56);compFrame.appendChild(h1);h1.x=24;h1.y=by+90;
  const nav=makeBottomNav("Bottom Nav / Account",3);nav.x=24;nav.y=by+170;compFrame.appendChild(nav);
  const navhome=makeBottomNav("Bottom Nav / Home",0);navhome.x=460;navhome.y=by+170;compFrame.appendChild(navhome);

