function makeFrame(name,x,y,w,h){
  const f=figma.createFrame(); f.name=name; f.resize(w,h); f.x=x; f.y=y;
  f.clipsContent=false; f.fills=[];
  ws.appendChild(f);
  return f;
}
function rect(parent,name,w,h,rx,fill){
  const r=figma.createRectangle(); r.name=name; r.resize(w,h);
  if(rx!==undefined) r.cornerRadius=rx;
  r.fills=[{type:'SOLID',color:fill}];
  parent.appendChild(r); return r;
}
function text(parent,name,str,size,weight,color,x,y){
  const t=figma.createText(); t.name=name; t.characters=str;
  const fam = (weight==="Semi Bold"||weight==="Bold"||weight==="Medium") ? "DM Sans":"Inter";
  t.fontName={family: fam, style: weight};
  t.fontSize=size; t.fills=[{type:'SOLID',color:color}];
  t.x=x; t.y=y;
  parent.appendChild(t); return t;
}
// place icon instance
function icon(parent,name,compId,x,y,color){
  const i=figma.createInstanceFromNode(figma.getNodeById(compId));
  i.name=name; i.x=x; i.y=y;
  if(i.children && i.children.length){
    try{ 
      // recolor vector
      const paths=i.findAll(n=>n.type==="VECTOR");
      if(paths.length){
        paths.forEach(p=>{ if(p.fills && Array.isArray(p.fills) && p.fills.length) p.fills=[{type:'SOLID',color:color}]; });
      }
    }catch(e){}
  }
  parent.appendChild(i);
  return i;
}

