// ---------- Text Field builder (reusable helper) ----------
// type in {normal,error}; returns children added to parent manually
async function textField(parent, x, y, w, label, value, placeholder, opts){
  opts=opts||{};
  const h=opts.h?opts.h:60;
  const outer=figma.createFrame(); outer.name=label; outer.resize(w,h); outer.x=x; outer.y=y; outer.fills=[FIELD]; outer.cornerRadius=20; outer.clipsContent=true;
  // optional field border when error/focused
  if(opts.error){ outer.strokes=[ERROR]; outer.strokeWeight=1.5; }
  outer.layoutMode="VERTICAL"; outer.paddingLeft=18; outer.paddingRight=18; outer.itemSpacing=2; outer.paddingTop=10; outer.primaryAxisAlignItems="CENTER"; outer.counterAxisAlignItems="MIN";
  if(opts.isErrorState){
    const lbl=figma.createText(); lbl.fontName={family:"Inter",style:"Regular"}; lbl.fontSize=11; lbl.characters=value; lbl.fills=[ERROR]; outer.appendChild(lbl);
    const inp=figma.createText(); inp.fontName={family:"Inter",style:"Regular"}; inp.fontSize=15; inp.characters="jonas.macroni@invest"; inp.fills=[TEXT]; outer.appendChild(inp);
  } else {
    const lbl=figma.createText(); lbl.fontName={family:"Inter",style:"Regular"}; lbl.fontSize=11; lbl.characters=label; lbl.fills=[SUB]; outer.appendChild(lbl);
    const inp=figma.createText(); inp.fontName={family:"Inter",style:"Regular"}; inp.fontSize=15; inp.characters=value||""; inp.fills=[TEXT]; outer.appendChild(inp);
  }
  parent.appendChild(outer);
  return outer;
}

