function describe(node,indent){
  const pad="  ".repeat(indent);
  let s=pad+node.name+"|"+node.id+"|"+node.type+"|"+Math.round(node.width)+"x"+Math.round(node.height);
  if(node.type==="TEXT"){ s+=" chars='"+node.characters+"' fontSize="+node.fontSize; }
  if(node.type==="FRAME"||node.type==="COMPONENT"||node.type==="INSTANCE"){ s+=" layout="+JSON.stringify(node.layoutMode)+" itemSpacing="+node.itemSpacing; }
  return s;
}
function walk(node,indent){
  let out=[describe(node,indent)];
  if(node.children){ for(const c of node.children){ out=out.concat(walk(c,indent+1)); } }
  return out;
}
