// Create a reusable field text helper
const makeText=(content,family,style,size,fill,opts)=>{
  const t=figma.createText();
  t.fontName={family,style};
  t.fontSize=size;
  t.characters=content;
  t.fills=[{type:'SOLID',color:fill}];
  if(opts&&opts.x!=null)t.x=opts.x;
  if(opts&&opts.y!=null)t.y=opts.y;
  if(opts&&opts.bold){ t.fontName={family,style:'Semi Bold'}; }
  return t;
};

