// function to build a rounded field pillow
function addField(parent,x,y,labelText,placeholder,value,border){
  // label
  const label=makeText(labelText,"Inter","Regular",13,GRAY); label.x=x+6; label.y=y-20; parent.appendChild(label);
  // field bg
  const bg=figma.createFrame(); bg.name="Field"; bg.x=x; bg.y=y; bg.resize(352,52); bg.cornerRadius=16;
  bg.fills=[{type:'SOLID',color:LIGHTGRAY}];
  bg.strokeWeight=1;
  bg.strokes=border?[{type:'SOLID',color:{r:0.9,g:0.25,b:0.22}}]:[];
  parent.appendChild(bg);
  // value/placeholder text inside
  const txt=makeText(value||placeholder,"Inter","Regular",15,value?INK:GRAY); txt.x=x+16; txt.y=y+16; parent.appendChild(txt);
  return bg;
}

