// Helper to set a TextField instance's content
function setField(frameId, childNameIdx, label, value){
  const field=figma.getNodeById(childNameIdx);
  if(!field){ console.log("no field", childNameIdx); return; }
  // find text child
  let found=null;
  function walk(n){
    if(n.type==="TEXT"){ found=n; return; }
    if(n.children){ for(const c of n.children){ walk(c); } }
  }
  walk(field);
  if(found){ found.characters=value; }
}

