// Tabs
function makeTab(name,iconNodeId,active,x){
  const grp=figma.createFrame(); grp.name=name; grp.x=x; grp.y=10; grp.resize(84,64);
  grp.layoutMode="VERTICAL"; grp.primaryAxisAlignItems="CENTER"; grp.counterAxisAlignItems="CENTER"; grp.itemSpacing=4;
  const icon=figma.getNodeById(iconNodeId).clone();
  icon.name="icon";
  if(active){ tryForEachFill(icon, primary); }
  grp.appendChild(icon);
  const t=figma.createText(); t.fontName={family:"Inter",style:"Regular"}; t.fontSize=10; t.characters=name;
  t.fills=[{type:'SOLID',color: active?{r:primary.r,g:primary.g,b:primary.b}:{r:0.55,g:0.6,b:0.58}}];
  grp.appendChild(t);
  return grp;
}
function tryForEachFill(n,c){
  try{ if(n.fills && Array.isArray(n.fills) && n.fills.length){ const f=n.fills[0]; if(f.type==="SOLID"){ n.fills=[{type:'SOLID',color:c}]; }else if(f.type===undefined){ n.fills=[{type:'SOLID',color:c}]; } } if(n.children){ for(const ch of n.children) tryForEachFill(ch,c);} }catch(e){}
}
