const txt=(parent,x,y,w,str,size,fill,variant)=>{
  const t=figma.createText();
  t.fontName={family:variant||"Inter",style: size>20?"Semi Bold":"Semi Bold"};
  t.characters=str; t.fontSize=size; t.fills=Array.isArray(fill)?fill:[fill];
  t.resize(w,size*1.4);
  parent.appendChild(t); t.x=x; t.y=y; return t;
};
const row=(x,y,w,h)=>{
  const r=figma.createFrame(); r.resize(w,h); r.fills=[WHITE];
